public sealed class CreateUserValidator : AbstractValidator<CreateUserRequest>
{
    public CreateUserValidator(IUserRepository users)
    {
        RuleFor(x => x.Name)
            .NotEmpty().MinimumLength(2).MaximumLength(100);

        RuleFor(x => x.Email)
            .NotEmpty().EmailAddress()
            .MustAsync(async (email, ct) => !await users.ExistsAsync(email, ct))
            .WithMessage("Email is already registered.");

        RuleFor(x => x.Password)
            .MinimumLength(8)
            .When(x => x.AccountType == AccountType.Standard);

        RuleFor(x => x.Age).InclusiveBetween(13, 120);
    }
}

