[Fact]
public void Should_fail_when_email_invalid()
{
    var validator = new CreateUserValidator(new FakeUserRepository());
    var result = validator.TestValidate(new CreateUserRequest
    {
        Name = "Ada",
        Email = "bad",
        Age = 30,
        Password = "ValidPass1",
        AccountType = AccountType.Standard
    });

    result.ShouldHaveValidationErrorFor(x => x.Email);
    result.ShouldNotHaveValidationErrorFor(x => x.Name);
}

public sealed class ValidationFilter<T>(IValidator<T> validator) : IEndpointFilter
{
    public async ValueTask<object?> InvokeAsync(
        EndpointFilterInvocationContext context, EndpointFilterDelegate next)
    {
        var model = context.Arguments.OfType<T>().FirstOrDefault();
        if (model is null) return Results.BadRequest("Missing body.");

        var result = await validator.ValidateAsync(model, context.HttpContext.RequestAborted);
        if (!result.IsValid)
        {
            var errors = result.Errors
                .GroupBy(e => e.PropertyName)
                .ToDictionary(g => g.Key, g => g.Select(e => e.ErrorMessage).ToArray());
            return Results.ValidationProblem(errors);
        }
        return await next(context);
    }
}

